package edid

import "fmt"

// Profiles lists the named EDID profiles glkvm accepts on the command line.
// chromebook is chromebook-1600 under its short name.
var Profiles = []string{"4k", "2k", "1k", "chromebook", "chromebook-1600", "chromebook-1412", "chromebook-1200"}

var presetKeys = map[string]string{
	"4k": "E3840x2160",
	"2k": "E2560x1440",
	"1k": "E1920x1080",
}

var embeddedHex = map[string]string{
	"chromebook":      Chromebook1600Hex,
	"chromebook-1600": Chromebook1600Hex,
	"chromebook-1412": Chromebook1412Hex,
	"chromebook-1200": Chromebook1200Hex,
}

// PresetKey resolves a named profile to either a device-side preset key
// (key non-empty, embedded empty) or an embedded EDID hex blob to upload
// directly (key empty, embedded non-empty). It errors for unknown profiles.
func PresetKey(profile string) (key string, embedded string, err error) {
	if h, ok := embeddedHex[profile]; ok {
		return "", h, nil
	}
	if k, ok := presetKeys[profile]; ok {
		return k, "", nil
	}
	return "", "", fmt.Errorf("unknown edid profile %q, want one of %v", profile, Profiles)
}

// The Chromebook EDIDs are the GLKVM 2K EDID with its first detailed timing
// replaced by a CVT mode from cvt(1). 1412x880 shifts cvt's 1416x880 timing
// by 4 pixels of front porch, since cvt rounds widths to 8.

// Chromebook1600Hex is 1600x1000@59.87, 132.25 MHz.
const Chromebook1600Hex = ""

// Chromebook1412Hex is 1412x880@59.87, 102.00 MHz.
const Chromebook1412Hex = ""

// Chromebook1200Hex is the gsv1127x's native 1200x752@59.82, 73.25 MHz,
// matching the device preset E1200x752CB byte for byte.
const Chromebook1200Hex = ""
